parameters.query:
-- The association's page of its community members, see
-- db/init/29-members.sql.
SELECT value AS url FROM app_settings WHERE key = 'members_page_url';

parameters.jsCode:
// The association's members page: its community members by name and
// website, under two headings, päättävät (voting) and kannattavat
// (supporting) yhteisöjäsenet. Only the organisations are read; the
// association's individual members are on another page and are never read.
// What is found goes to sync_members(), see db/init/29-members.sql.
const url = $json.url;
const html = String(await this.helpers.httpRequest({
  url, timeout: 15000, json: false,
  headers: { 'User-Agent': 'DFP newsletter bot (HAMK student project)' },
}));

const unescape = (s) => String(s)
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#0?39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim();

// Where a heading of the page's own content starts; the menus repeat the
// same words as links, not as headings.
const headingAt = (words) => {
  const m = html.match(new RegExp(`<h[1-6][^>]*>\\s*${words}\\s*</h[1-6]>`, 'i'));
  return m ? m.index : -1;
};
const voting = headingAt('Päättävät yhteisöjäsenet');
const supporting = headingAt('Kannattavat yhteisöjäsenet');
if (voting < 0 || supporting < 0 || supporting < voting) {
  throw new Error(`The members page ${url} no longer has its two headings of community members`);
}
const afterSupporting = html.slice(supporting + 4).search(/<h[1-6][\s>]/i);
const end = afterSupporting >= 0 ? supporting + 4 + afterSupporting : html.length;

// A member's address as articles are matched against it: no www., and no
// language part such as fi.itslearning.com.
const hostOf = (href) => {
  const m = href.match(/^https?:\/\/([^\/?#:]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '').replace(/^(fi|en|sv)\./, '') : '';
};
const SOCIAL = /(^|\.)(facebook|instagram|linkedin|twitter|x|youtube|tiktok)\.com$/;

const members = [];
const read = (part, kind) => {
  for (const m of part.matchAll(/<li[^>]*>\s*<a[^>]+href=["'](https?:\/\/[^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)) {
    const host = hostOf(m[1]);
    const name = unescape(m[2].replace(/<[^>]+>/g, ' '));
    if (!host || !name || host.endsWith('eoppimiskeskus.fi') || SOCIAL.test(host)) continue;
    members.push({ name, website: m[1], host, kind });
  }
};
read(html.slice(voting, supporting), 'voting');
read(html.slice(supporting, end), 'supporting');

// A handful would mean the page changed, not that the members left; the
// database refuses fewer than five as well.
if (members.length < 5) throw new Error(`The members page ${url} gave only ${members.length} members; its layout may have changed`);
return { json: { members, count: members.length } };

parameters.query:
-- Adds the new members, keeps the rest up to date, and marks the ones no
-- longer on the page. Refuses a page that gives fewer than five.
SELECT * FROM sync_members($1::jsonb);
